export const authOptions = {
  providers: [
    GitHubProvider({ clientId: process.env.GITHUB_ID, clientSecret: process.env.GITHUB_SECRET }),
  ],
  secret: process.env.NEXTAUTH_SECRET,
  callbacks: {
    async session({ session, token }) {
      session.user.id = token.sub;
      return session;
    },
  },
};

// app/actions.js
'use server';
import { prisma } from '@/lib/prisma';
import { revalidatePath } from 'next/cache';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { z } from 'zod';

const commentSchema = z.object({
  text: z.string().min(1, 'Comment cannot be empty').max(500),
});

export async function addComment(postSlug, prevState, formData) {
  const session = await getServerSession(authOptions);
  if (!session) {
    return { error: 'You must be signed in to comment.' };
  }

  const text = formData.get('text');
  const result = commentSchema.safeParse({ text });
  if (!result.success) {
    return { errors: result.error.flatten().fieldErrors };
  }

  const post = await prisma.post.findUnique({ where: { slug: postSlug } });
  if (!post) return { error: 'Post not found.' };

  await prisma.comment.create({
    data: {
      text: result.data.text,
      postId: post.id,
      userId: session.user.id,
    },
  });

  revalidatePath(`/posts/${postSlug}`);
  return { success: true };
}

// components/CommentForm.js
'use client';
import { useSession, signIn } from 'next-auth/react';
import { useFormState } from 'react-dom';
import { addComment } from '@/app/actions';

export default function CommentForm({ postSlug }) {
  const { data: session, status } = useSession();
  const addCommentWithSlug = addComment.bind(null, postSlug);
  const [state, formAction] = useFormState(addCommentWithSlug, {});

  if (status === 'loading') return <p>Loading...</p>;
  if (!session) return <button onClick={() => signIn()}>Sign in to comment</button>;

  return (
    <form action={formAction} className="mt-4">
      <textarea name="text" className="border p-2 w-full" placeholder="Write a comment..." />
      {state?.errors?.text && <p className="text-red-500">{state.errors.text[0]}</p>}
      <button type="submit" className="mt-2 px-4 py-2 bg-blue-500 text-white rounded">Post Comment</button>
      {state?.success && <p className="text-green-500 mt-2">Comment added!</p>}
      {state?.error && <p className="text-red-500">{state.error}</p>}
    </form>
  );
}

